schema.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/pr-mentoring-session-protocol.json",
  "title": "PR mentoring session record",
  "type": "object",
  "required": ["session", "owner", "inputs", "fix_commit", "progression", "decision", "junior_confirmation", "evidence", "status"],
  "additionalProperties": false,
  "definitions": {
    "handle": {"type": "string", "pattern": "^[a-z-]+:[a-z0-9._-]+$"},
    "date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},
    "url": {"type": "string", "pattern": "^https://"},
    "behaviour": {"type": "string", "minLength": 15, "pattern": "^(?![\\s\\S]*([Bb]e more careful|[Tt]hink about|[Bb]e careful|[Kk]eep this in mind|[Nn]ext time|[Ss]loppy|[Rr]ushed|[Cc]areless))"}
  },
  "properties": {
    "__faion_header__": {"type": "object"},
    "session": {
      "type": "object",
      "required": ["pr_url", "junior", "senior", "date", "record_readable_by_junior", "evaluation_use"],
      "additionalProperties": false,
      "properties": {
        "pr_url": {"type": "string", "pattern": "^https://[^\\s,]+/(pull|merge_requests|pull-requests)/[0-9]+$"},
        "junior": {"$ref": "#/definitions/handle"},
        "senior": {"$ref": "#/definitions/handle"},
        "date": {"$ref": "#/definitions/date"},
        "record_readable_by_junior": {"type": "boolean", "const": true},
        "evaluation_use": {"type": "string", "enum": ["not-used-in-evaluation", "aggregated-in-performance-review", "aggregated-in-promotion-case"]}
      }
    },
    "owner": {"$ref": "#/definitions/handle"},
    "inputs": {
      "type": "array",
      "minItems": 6,
      "allOf": [
        {"contains": {"properties": {"name": {"const": "learning_goal"}}}},
        {"contains": {"properties": {"name": {"const": "observed_gap"}}}},
        {"contains": {"properties": {"name": {"const": "restated_gap"}}}},
        {"contains": {"properties": {"name": {"const": "comment_counts"}}}},
        {"contains": {"properties": {"name": {"const": "deferred_findings"}}}},
        {"contains": {"properties": {"name": {"const": "session_outcome"}}}}
      ],
      "items": {
        "type": "object",
        "required": ["name", "value"],
        "additionalProperties": false,
        "properties": {
          "name": {"type": "string", "enum": ["learning_goal", "observed_gap", "restated_gap", "comment_counts", "deferred_findings", "session_outcome"]},
          "value": {}
        },
        "allOf": [
          {"if": {"properties": {"name": {"const": "learning_goal"}}},
           "then": {"properties": {"value": {"$ref": "#/definitions/behaviour"}}}},
          {"if": {"properties": {"name": {"const": "observed_gap"}}},
           "then": {"properties": {"value": {
             "type": "object",
             "required": ["did", "should"],
             "additionalProperties": false,
             "properties": {"did": {"$ref": "#/definitions/behaviour"}, "should": {"$ref": "#/definitions/behaviour"}}}}}},
          {"if": {"properties": {"name": {"const": "restated_gap"}}},
           "then": {"properties": {"value": {"type": "string", "minLength": 20}}}},
          {"if": {"properties": {"name": {"const": "comment_counts"}}},
           "then": {"properties": {"value": {
             "type": "object",
             "required": ["issue", "suggestion", "question", "nitpick", "praise", "thought"],
             "additionalProperties": false,
             "properties": {
               "issue": {"type": "integer", "minimum": 0},
               "suggestion": {"type": "integer", "minimum": 0},
               "question": {"type": "integer", "minimum": 0},
               "nitpick": {"type": "integer", "minimum": 0},
               "praise": {"type": "integer", "minimum": 1},
               "thought": {"type": "integer", "minimum": 0}}}}}},
          {"if": {"properties": {"name": {"const": "deferred_findings"}}},
           "then": {"properties": {"value": {
             "type": "array",
             "items": {
               "type": "object",
               "required": ["url", "note"],
               "additionalProperties": false,
               "properties": {"url": {"$ref": "#/definitions/url"}, "note": {"type": "string", "minLength": 8}}}}}}},
          {"if": {"properties": {"name": {"const": "session_outcome"}}},
           "then": {"properties": {"value": {"type": "string", "enum": ["learning_goal_addressed", "learning_goal_not_addressed"]}}}}
        ]
      }
    },
    "fix_commit": {
      "oneOf": [
        {"type": "null"},
        {
          "type": "object",
          "required": ["url", "author"],
          "additionalProperties": false,
          "properties": {"url": {"$ref": "#/definitions/url"}, "author": {"$ref": "#/definitions/handle"}}
        }
      ]
    },
    "progression": {
      "type": "object",
      "required": ["prior_record_url", "not_demonstrated_streak"],
      "additionalProperties": false,
      "properties": {
        "prior_record_url": {"type": ["string", "null"], "pattern": "^https://"},
        "prior_action_status": {"type": "string", "enum": ["demonstrated", "partial", "not-demonstrated"]},
        "not_demonstrated_streak": {"type": "integer", "minimum": 0}
      },
      "allOf": [
        {"if": {"properties": {"prior_record_url": {"type": "string"}}}, "then": {"required": ["prior_action_status"]}},
        {"if": {"properties": {"prior_record_url": {"type": "null"}}}, "then": {"properties": {"not_demonstrated_streak": {"const": 0}}}}
      ]
    },
    "decision": {
      "type": "object",
      "required": ["follow_up_action", "demonstrate_in"],
      "additionalProperties": false,
      "properties": {
        "follow_up_action": {"$ref": "#/definitions/behaviour"},
        "demonstrate_in": {
          "type": "object",
          "required": ["window", "url"],
          "additionalProperties": false,
          "properties": {
            "window": {
              "oneOf": [
                {"type": "integer", "minimum": 1, "maximum": 14},
                {"type": "string", "const": "next-two-prs"}
              ]
            },
            "url": {"type": ["string", "null"], "pattern": "^https://"}
          }
        },
        "escalation": {
          "type": "object",
          "required": ["intervention", "escalated_to"],
          "additionalProperties": false,
          "properties": {
            "intervention": {"type": "string", "enum": ["pairing-session", "structured-exercise", "course"]},
            "escalated_to": {"$ref": "#/definitions/handle"}
          }
        }
      }
    },
    "junior_confirmation": {
      "type": "object",
      "required": ["method", "url", "confirmed_at"],
      "additionalProperties": false,
      "properties": {
        "method": {"type": "string", "enum": ["comment", "reaction", "co-authorship"]},
        "url": {"$ref": "#/definitions/url"},
        "confirmed_at": {"$ref": "#/definitions/date"}
      }
    },
    "evidence": {
      "type": "array",
      "minItems": 2,
      "items": {"$ref": "#/definitions/url"},
      "contains": {"pattern": "#(discussion_r[0-9]+|L[0-9]+|note_[0-9]+|diff)"}
    },
    "status": {"type": "string", "enum": ["open", "closed"]}
  }
}

output-contract.example:
{
  "session": {
    "pr_url": "https://github.com/acme/billing/pull/412",
    "junior": "swe:bohdan",
    "senior": "swe:alice",
    "date": "2026-09-09",
    "record_readable_by_junior": true,
    "evaluation_use": "not-used-in-evaluation"
  },
  "owner": "swe:alice",
  "inputs": [
    {"name": "learning_goal", "value": "writes a migration that is safe to re-run: every ALTER guarded by IF NOT EXISTS or a state check"},
    {"name": "observed_gap", "value": {
      "did": "migrations/0042.py line 18 runs ALTER TABLE invoices ADD COLUMN vat_rate unconditionally, so a second apply fails",
      "should": "check for the column with IF NOT EXISTS (or inspect information_schema) so the migration can run twice without error"
    }},
    {"name": "restated_gap", "value": "my ALTER assumes the column is absent; if the deploy retries the migration it crashes, so I need to guard the ADD COLUMN"},
    {"name": "comment_counts", "value": {"issue": 1, "suggestion": 1, "question": 1, "nitpick": 2, "praise": 1, "thought": 0}},
    {"name": "deferred_findings", "value": [
      {"url": "https://github.com/acme/billing/pull/412/files#diff-9a1L44", "note": "unused import of Decimal; posted as an ordinary nitpick after the session"}
    ]},
    {"name": "session_outcome", "value": "learning_goal_addressed"}
  ],
  "fix_commit": {"url": "https://github.com/acme/billing/pull/412/commits/c4d5e6f", "author": "swe:bohdan"},
  "progression": {
    "prior_record_url": "https://github.com/acme/billing/blob/main/.product/pr-mentoring-session-protocol/bohdan-2026-08-26.md",
    "prior_action_status": "not-demonstrated",
    "not_demonstrated_streak": 2
  },
  "decision": {
    "follow_up_action": "opens the next migration PR with every ALTER guarded and a re-run test in the PR description",
    "demonstrate_in": {"window": 14, "url": "https://github.com/acme/billing/pull/420"}
  },
  "junior_confirmation": {"method": "comment", "url": "https://github.com/acme/billing/pull/412#issuecomment-2210001", "confirmed_at": "2026-09-09"},
  "evidence": [
    "https://github.com/acme/billing/pull/412/files#discussion_r1987001",
    "https://github.com/acme/billing/blob/main/.product/pr-mentoring-session-protocol/bohdan-2026-08-26.md",
    "https://github.com/acme/billing/pull/420"
  ],
  "status": "closed"
}

{
  "session": {
    "pr_url": "https://github.com/acme/billing/pull/412",
    "junior": "swe:bohdan",
    "senior": "swe:alice",
    "date": "2026-09-09",
    "record_readable_by_junior": true,
    "evaluation_use": "not-used-in-evaluation"
  },
  "owner": "swe:alice",
  "inputs": [
    {"name": "learning_goal", "value": "be more careful with migrations and think about edge cases"},
    {"name": "observed_gap", "value": {
      "did": "the migration was rushed and sloppy",
      "should": "take more time before opening the PR"
    }},
    {"name": "restated_gap", "value": "I will be more careful next time with migrations"},
    {"name": "comment_counts", "value": {"issue": 1, "suggestion": 0, "question": 0, "nitpick": 14, "praise": 0, "thought": 0}},
    {"name": "deferred_findings", "value": []},
    {"name": "session_outcome", "value": "learning_goal_addressed"}
  ],
  "fix_commit": {"url": "https://github.com/acme/billing/pull/412/commits/a1b2c3d", "author": "swe:alice"},
  "progression": {
    "prior_record_url": "https://github.com/acme/billing/blob/main/.product/pr-mentoring-session-protocol/bohdan-2026-08-26.md",
    "not_demonstrated_streak": 3
  },
  "decision": {
    "follow_up_action": "keep this in mind next time",
    "demonstrate_in": {"window": 30, "url": null}
  },
  "junior_confirmation": {"method": "comment", "url": "https://github.com/acme/billing/pull/412#issuecomment-2210001", "confirmed_at": "2026-09-09"},
  "evidence": [
    "https://github.com/acme/billing/pull/412",
    "https://github.com/acme/billing/blob/main/.product/pr-mentoring-session-protocol/bohdan-2026-08-26.md"
  ],
  "status": "closed"
}
